class Codec:
    def encode(self, root):
        if not root: return None
        bn = TreeNode(root.val)
        if root.children:
            bn.left = self.encode(root.children[0])
        cur = bn.left
        for i in range(1, len(root.children)):
            cur.right = self.encode(root.children[i])
            cur = cur.right
        return bn
