            cur = cur.right
        return node

class AllOne:
    def __init__(self):
        from collections import defaultdict
        self.key_count = {}
        self.count_keys = defaultdict(set)
    def inc(self, key: str) -> None:
        old = self.key_count.get(key, 0)
        self.key_count[key] = old + 1
        if old: self.count_keys[old].discard(key)
        if old and not self.count_keys[old]: del self.count_keys[old]
        self.count_keys[old+1].add(key)
    def dec(self, key: str) -> None:
        old = self.key_count[key]
        self.count_keys[old].discard(key)
        if not self.count_keys[old]: del self.count_keys[old]
        if old == 1: del self.key_count[key]
        else: self.key_count[key] = old-1; self.count_keys[old-1].add(key)
    def getMaxKey(self) -> str:
        if not self.count_keys: return ''
        return next(iter(self.count_keys[max(self.count_keys)]))
    def getMinKey(self) -> str:
        if not self.count_keys: return ''
        return next(iter(self.count_keys[min(self.count_keys)]))

