class Solution:
    def parseTernary(self, expression: str) -> str:
        stack = []
        i = len(expression) - 1
        while i >= 0:
            if expression[i] == '?':
                first = stack.pop()
                second = stack.pop()
                stack.append(first if expression[i-1] == 'T' else second)
                i -= 2
            elif expression[i] != ':':
                stack.append(expression[i])
                i -= 1
            else:
                i -= 1
        return stack[0]

class Solution:
    def findKthNumber(self, n: int, k: int) -> int:
        def count_steps(prefix, n):
            steps = 0
            first, last = prefix, prefix
            while first <= n:
                steps += min(n + 1, last + 1) - first
                first *= 10; last = last * 10 + 9
            return steps
        curr = 1; k -= 1
        while k > 0:
            steps = count_steps(curr, n)
            if steps <= k:
                k -= steps; curr += 1
            else:
