class Solution:
    def sequenceReconstruction(self, org: list[int], sequences: list[list[int]]) -> bool:
        from collections import defaultdict, deque
        n = len(org)
        graph = defaultdict(set)
        indeg = [0] * (n + 1)
        nodes = set()
        for seq in sequences:
            nodes.update(seq)
            for i in range(len(seq)-1):
                if seq[i+1] not in graph[seq[i]]:
                    graph[seq[i]].add(seq[i+1])
                    indeg[seq[i+1]] += 1
        if nodes != set(range(1, n+1)): return False
        q = deque(i for i in range(1, n+1) if indeg[i] == 0)
        idx = 0
        while q:
            if len(q) > 1: return False
            node = q.popleft()
            if idx >= n or node != org[idx]: return False
            idx += 1
            for nb in graph[node]:
                indeg[nb] -= 1
                if indeg[nb] == 0: q.append(nb)
        return idx == n

