class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        if maxChoosableInteger * (maxChoosableInteger+1) // 2 < desiredTotal: return False
        if desiredTotal <= 0: return True
        memo = {}
        def dp(mask, total):
            if mask in memo: return memo[mask]
            for i in range(1, maxChoosableInteger+1):
                if mask & (1<<i): continue
                if i >= total or not dp(mask|(1<<i), total-i):
                    memo[mask] = True
                    return True
            memo[mask] = False
            return False
        return dp(0, desiredTotal)

class Solution:
    def minTransfers(self, transactions: list[list[int]]) -> int:
        from collections import defaultdict
        balance = defaultdict(int)
        for a, b, amt in transactions:
            balance[a] -= amt; balance[b] += amt
        debts = [v for v in balance.values() if v != 0]
        def bt(idx):
            while idx < len(debts) and debts[idx] == 0: idx += 1
            if idx == len(debts): return 0
            res = float('inf')
            for i in range(idx+1, len(debts)):
                if debts[i] * debts[idx] < 0:
                    debts[i] += debts[idx]
                    res = min(res, 1 + bt(idx+1))
                    debts[i] -= debts[idx]
            return res
        return bt(0)

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)): return 0
        s2_count = 0; s2_idx = 0
        recall = {}
        for i in range(1, n1+1):
            for ch in s1:
                if ch == s2[s2_idx]:
                    s2_idx += 1
                    if s2_idx == len(s2):
                        s2_count += 1; s2_idx = 0
            if s2_idx in recall:
                prev_i, prev_count = recall[s2_idx]
                cycle_len = i - prev_i
                cycle_count = s2_count - prev_count
                remaining = n1 - i
                full_cycles = remaining // cycle_len
                s2_count += full_cycles * cycle_count
                for _ in range(remaining % cycle_len):
                    for ch in s1:
                        if ch == s2[s2_idx]:
                            s2_idx += 1
                            if s2_idx == len(s2):
                                s2_count += 1; s2_idx = 0
                return s2_count // n2
            recall[s2_idx] = (i, s2_count)
        return s2_count // n2

