class Solution:
    def isConvex(self, points: list[list[int]]) -> bool:
        n = len(points)
        sign = 0
        for i in range(n):
            a, b, c = points[i], points[(i+1)%n], points[(i+2)%n]
            cross = (b[0]-a[0])*(c[1]-b[1]) - (b[1]-a[1])*(c[0]-b[0])
            if cross != 0:
                if sign == 0: sign = 1 if cross > 0 else -1
                elif (cross > 0 and sign < 0) or (cross < 0 and sign > 0):
                    return False
        return True

