class Solution:
    def encode(self, s: str) -> str:
        n = len(s)
        dp = [[''] * n for _ in range(n)]
        for l in range(1, n+1):
            for i in range(n-l+1):
                j = i + l - 1
                sub = s[i:j+1]
                dp[i][j] = sub
                if l <= 4: continue
                for k in range(i, j):
                    cand = dp[i][k] + dp[k+1][j]
                    if len(cand) < len(dp[i][j]):
                        dp[i][j] = cand
                for k in range(1, l+1):
                    if l % k == 0 and sub[:k] * (l//k) == sub:
                        cand = f'{l//k}[{dp[i][i+k-1]}]'
                        if len(cand) < len(dp[i][j]):
                            dp[i][j] = cand
        return dp[0][n-1]

class Solution:
    def findAllConcatenatedWordsInADict(self, words: list[str]) -> list[str]:
        word_set = set(words)
        def canForm(word):
            dp = [False] * (len(word)+1)
            dp[0] = True
            for i in range(1, len(word)+1):
                for j in range(i):
                    if dp[j] and word[j:i] in word_set and word[j:i] != word:
