            zeros = s.count('0'); ones = s.count('1')
            for i in range(m, zeros-1, -1):
                for j in range(n, ones-1, -1):
                    dp[i][j] = max(dp[i][j], dp[i-zeros][j-ones]+1)
        return dp[m][n]

class Solution:
    def findRadius(self, houses: list[int], heaters: list[int]) -> int:
        import bisect
        heaters.sort()
        res = 0
        for h in houses:
            idx = bisect.bisect_left(heaters, h)
            dist = float('inf')
            if idx < len(heaters): dist = heaters[idx] - h
            if idx > 0: dist = min(dist, h - heaters[idx-1])
            res = max(res, dist)
        return res

class Solution:
    def findComplement(self, num: int) -> int:
        mask = (1 << num.bit_length()) - 1
        return num ^ mask

class Solution:
    def totalHammingDistance(self, nums: list[int]) -> int:
        n = len(nums)
        total = 0
        for bit in range(32):
            ones = sum(1 for x in nums if x & (1 << bit))
            total += ones * (n - ones)
        return total

class Solution:
    def __init__(self, radius: float, x_center: float, y_center: float):
        self.r = radius; self.x = x_center; self.y = y_center
    def randPoint(self) -> list[float]:
        import random, math
        theta = random.uniform(0, 2*math.pi)
        r = self.r * math.sqrt(random.random())
        return [self.x + r*math.cos(theta), self.y + r*math.sin(theta)]

class Solution:
    def largestPalindrome(self, n: int) -> int:
        if n == 1: return 9
        upper = 10**n - 1
        for i in range(upper, upper//10, -1):
            s = str(i)
            palin = int(s + s[::-1])
            j = upper
            while j * j >= palin:
                if palin % j == 0:
                    return palin % 1337
                j -= 1
        return 0

class Solution:
    def medianSlidingWindow(self, nums: list[int], k: int) -> list[float]:
        import heapq
        from collections import defaultdict
        small = []  # max heap (negated)
        large = []  # min heap
        delayed = defaultdict(int)
        def add(num):
            if not small or num <= -small[0]: heapq.heappush(small, -num)
            else: heapq.heappush(large, num)
        def balance():
            while len(small) > len(large) + 1:
                heapq.heappush(large, -heapq.heappop(small))
            while len(large) > len(small):
                heapq.heappush(small, -heapq.heappop(large))
        def remove(num):
            delayed[num] += 1
            if num <= -small[0]:
                if num == -small[0]: prune(small, True)
            else:
                if num == large[0]: prune(large, False)
        def prune(heap, is_small):
            while heap and delayed[(-heap[0] if is_small else heap[0])] > 0:
                val = -heapq.heappop(heap) if is_small else heapq.heappop(heap)
                delayed[val] -= 1
        def get_median():
            return -small[0] if k % 2 else (-small[0] + large[0]) / 2
        for i in range(k): add(nums[i])
        balance()
        res = [get_median()]
        for i in range(k, len(nums)):
            add(nums[i]); remove(nums[i-k]); balance()
            prune(small, True); prune(large, False)
            res.append(get_median())
        return res
